// Replays trace.json (generated by `node packages/cli/dist/index.js trace`). The page never
// computes run state itself: every node state shown here was produced by the core reducer.
// The only derived marks are presentational: which cells did not change since the previous
// event, which node an attempt belongs to, and the attempt labels (`implement#2`).

/** One glyph per node state. Shape carries the state; colour is never the only channel. */
const ASPECTS = [
  ["pending", "·", "pending"],
  ["ready", "○", "ready to start"],
  ["running", "●", "running"],
  ["unverified", "◐", "result awaiting acceptance"],
  // Decision 0005 (not implemented yet): a producer's result held until its verifying nodes finish.
  ["verifying", "◒", "result waiting for its checks"],
  ["accepted", "✓", "accepted"],
  // Decision 0005: a consumed result that was invalidated when its producer was repaired.
  ["invalidated", "↺", "result thrown out, waiting again"],
  ["failed", "✗", "rejected, failed or exhausted"],
  ["cancelled", "⊘", "cancelled"],
];
const GLYPH = Object.fromEntries(ASPECTS.map(([aspect, glyph]) => [aspect, glyph]));
const RUN_GLYPH = { running: "●", cancelling: "◌", succeeded: "✓", failed: "✗", cancelled: "⊘" };

const view = { trace: null, scenario: null, step: 0, labels: new Map() };

const byId = (id) => document.getElementById(id);

function html(tag, attributes = {}, ...children) {
  const element = document.createElement(tag);
  for (const [name, value] of Object.entries(attributes)) {
    if (value !== undefined && value !== null && value !== false) element.setAttribute(name, String(value));
  }
  element.append(...children.flat().filter((child) => child !== undefined && child !== null && child !== false));
  return element;
}

const hidden = (text) => html("span", { class: "visually-hidden" }, text);
const pad = (index) => String(index + 1).padStart(2, "0");

/** Node state folded into one aspect: execution progress and result trust together. */
function aspectOf(node) {
  if (node.execution === "cancelled") return "cancelled";
  if (node.execution === "failed" || node.execution === "exhausted" || node.disposition === "rejected") {
    return "failed";
  }
  if (node.disposition === "invalidated") return "invalidated";
  if (node.disposition === "accepted") return "accepted";
  if (node.disposition === "verifying") return "verifying";
  if (node.execution === "result_ready") return "unverified";
  if (node.execution === "running") return "running";
  if (node.execution === "ready") return "ready";
  return "pending";
}

function describeNode(node) {
  const parts = [node.execution.replaceAll("_", " ")];
  if (node.disposition !== null) parts.push(node.disposition);
  if (node.failureCategory) parts.push(node.failureCategory);
  parts.push(`${node.attemptCount} ${node.attemptCount === 1 ? "attempt" : "attempts"}`);
  return parts.join(", ");
}

/** attemptId -> { node, label }, numbering each node's attempts in order of first dispatch. */
function attemptLabels(scenario) {
  const labels = new Map();
  const counts = new Map();
  const note = (nodeId, attemptId) => {
    if (!nodeId || !attemptId || labels.has(attemptId)) return;
    const count = (counts.get(nodeId) ?? 0) + 1;
    counts.set(nodeId, count);
    labels.set(attemptId, { node: nodeId, label: `${nodeId}#${count}` });
  };
  for (const step of scenario.steps) {
    for (const command of step.commands) if (command.type === "dispatch") note(command.nodeId, command.attemptId);
    note(step.event.nodeId, step.event.attemptId);
  }
  return labels;
}

const label = (attemptId) => view.labels.get(attemptId)?.label ?? attemptId;
const nodeOf = (event) => event.nodeId ?? view.labels.get(event.attemptId)?.node ?? "run";

/** A hash identifier shortened in the middle: sha256:d8144116…3a283a. */
function shortId(id) {
  const match = /^(sha256:)([0-9a-f]{20,})$/.exec(id);
  return match === null ? id : `${match[1]}${match[2].slice(0, 8)}…${match[2].slice(-6)}`;
}

/** Reducer messages name attempts by hash; add the label so the reader can follow them. */
function withLabels(text) {
  return text.replace(/sha256:[0-9a-f]{20,}/g, (id) => {
    const known = view.labels.get(id);
    return known === undefined ? shortId(id) : `${known.label} (${shortId(id)})`;
  });
}

/** The event's arguments on one line, attempts by label. */
function argumentsOf(event) {
  const attempt = event.attemptId === undefined ? undefined : label(event.attemptId);
  const token = event.fencingToken === undefined ? undefined : `token ${event.fencingToken}`;
  switch (event.type) {
    case "run_started":
      return [
        `graph ${event.graph.id} r${event.graph.revision}`,
        `${event.graph.nodes.length} nodes`,
        `≤${event.policy.maxConcurrent} concurrent`,
      ].join(" · ");
    case "attempt_failed":
      return [attempt, token, event.category].filter(Boolean).join(" · ");
    case "acceptance_decided":
      return [`${attempt} ${event.decision}`, ...(event.receiptIds ?? [])].join(" · ");
    case "cancel_requested":
      return `“${event.reason}”`;
    default:
      return [attempt, token].filter(Boolean).join(" · ");
  }
}

function describeCommand(command) {
  switch (command.type) {
    case "dispatch":
      return `dispatch ${label(command.attemptId)} with token ${command.fencingToken}`;
    case "evaluate_acceptance":
      return `evaluate_acceptance for ${label(command.attemptId)}`;
    case "cancel_attempt":
      return `cancel_attempt ${label(command.attemptId)}`;
    case "complete_run":
      return `complete_run ${command.status}`;
    default: {
      const { type, ...rest } = command;
      return `${type} ${JSON.stringify(rest)}`;
    }
  }
}

function elapsed(scenario, step) {
  const seconds = Math.round((Date.parse(step.event.at) - Date.parse(scenario.steps[0].event.at)) / 1000);
  return Number.isFinite(seconds) ? `+${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}` : "";
}

const rejectedCount = (scenario) => scenario.steps.filter((step) => step.outcome === "rejected").length;

function renderScenarioList() {
  const list = byId("scenario-list");
  list.replaceChildren(
    ...view.trace.scenarios.map((scenario) => {
      const rejected = rejectedCount(scenario);
      return html(
        "li",
        {},
        html(
          "a",
          {
            href: `#${scenario.id}/1`,
            "aria-current": scenario.id === view.scenario.id ? "true" : undefined,
            "data-focus": `scenario-${scenario.id}`,
          },
          scenario.id,
          " ",
          html(
            "span",
            { class: "count" },
            `${scenario.steps.length}`,
            hidden(" events"),
            rejected > 0 ? [" · ", html("span", { class: "rejected" }, `${rejected}✗`, hidden(" rejected"))] : null,
          ),
        ),
      );
    }),
  );
}

function renderFacts(scenario) {
  const rejected = rejectedCount(scenario);
  const fact = (term, ...value) => [html("dt", {}, term), html("dd", {}, ...value)];
  const edges = scenario.graph.edges.map((edge) =>
    html(
      "span",
      { class: "edge" },
      `${edge.from} → ${edge.to} `,
      html(
        "span",
        { class: "condition" },
        edge.condition === "accepted" ? "(needs accepted result)" : "(needs a result)",
      ),
    ),
  );
  const { maxConcurrent, maxAttemptsPerNode } = scenario.policy;
  byId("facts").replaceChildren(
    ...fact("events", `${scenario.steps.length} · ${scenario.steps.length - rejected} applied · ${rejected} rejected`),
    ...fact("ended", scenario.finalStatus),
    ...fact("policy", `≤${maxConcurrent} concurrent, ≤${maxAttemptsPerNode} attempts per node`),
    ...fact("graph", edges.length > 0 ? edges : "no edges"),
  );
}

function renderMatrix(scenario) {
  const steps = scenario.steps;
  const columnClass = (index, extra) =>
    [steps[index].outcome === "rejected" ? "rejected" : "", index === view.step ? "selected" : "", extra]
      .filter(Boolean)
      .join(" ") || undefined;

  const head = html(
    "tr",
    {},
    html("th", { scope: "col" }, hidden("Row")),
    steps.map((step, index) =>
      html(
        "th",
        { scope: "col", class: columnClass(index), "data-step": index },
        pad(index),
        hidden(` ${step.event.type}`),
      ),
    ),
  );

  const row = (name, rowClass, cell) =>
    html(
      "tr",
      { class: rowClass },
      html("th", { scope: "row" }, name),
      steps.map((step, index) => {
        const { glyph, text, unchanged } = cell(step, index);
        return html(
          "td",
          { class: columnClass(index, unchanged ? "unchanged" : ""), title: text, "data-step": index },
          html("span", { "aria-hidden": "true" }, glyph),
          hidden(text),
        );
      }),
    );

  const nodeRows = scenario.graph.nodes.map(({ id }) =>
    row(id, "node", (step, index) => {
      const node = step.nodes[id];
      const before = index > 0 ? steps[index - 1].nodes[id] : undefined;
      return {
        glyph: GLYPH[aspectOf(node)],
        text: `${id}: ${describeNode(node)}`,
        unchanged: before !== undefined && JSON.stringify(before) === JSON.stringify(node),
      };
    }),
  );
  const runRow = row("run", "run", (step, index) => ({
    glyph: RUN_GLYPH[step.run.status] ?? "?",
    text: `run ${step.run.status}, ${step.run.permitsInUse} permits in use`,
    unchanged: index > 0 && JSON.stringify(steps[index - 1].run) === JSON.stringify(step.run),
  }));
  const reducerRow = row("reducer", "reducer", (step) =>
    step.outcome === "rejected"
      ? { glyph: "✗", text: `rejected: ${step.rejection?.code ?? "unknown"}`, unchanged: false }
      : { glyph: "ok", text: "applied", unchanged: true },
  );
  byId("matrix").replaceChildren(html("thead", {}, head), html("tbody", {}, nodeRows, runRow, reducerRow));

  const used = new Set(scenario.graph.nodes.flatMap(({ id }) => steps.map((step) => aspectOf(step.nodes[id]))));
  byId("legend").replaceChildren(
    ...ASPECTS.filter(([aspect]) => used.has(aspect)).map(([, glyph, text]) =>
      html("span", {}, html("span", { class: "glyph", "aria-hidden": "true" }, glyph), text),
    ),
    html("span", {}, "faint: unchanged since the previous event"),
    html("span", {}, "shaded column: rejected event, nothing changed"),
  );
}

function renderDetail(step) {
  const rejected = step.outcome === "rejected";
  const verdict = rejected
    ? html(
        "div",
        { class: "verdict" },
        html("p", { class: "code" }, `rejected: ${step.rejection?.code ?? "unknown"}`),
        step.rejection?.message
          ? html("p", { class: "message" }, withLabels(step.rejection.message).replace(/\.?$/, "."))
          : null,
        html("p", { class: "message" }, "Nothing changed."),
      )
    : html("div", { class: "verdict" }, html("p", {}, "applied"));
  const commands = html(
    "ul",
    { class: "commands", "aria-label": "Commands for the host" },
    step.commands.length > 0
      ? step.commands.map((command) =>
          html(
            "li",
            { title: JSON.stringify(command) },
            html("span", { "aria-hidden": "true" }, "→ "),
            describeCommand(command),
          ),
        )
      : html("li", { class: "none" }, "no commands for the host"),
  );
  return html(
    "div",
    { class: "detail", id: `detail-${step.index}` },
    html("p", { class: "note" }, step.note),
    html("div", { class: "decision" }, html("h3", {}, "reducer"), verdict, commands),
    html(
      "div",
      { class: "payload" },
      html("h3", {}, "event sent by the host"),
      html("pre", {}, JSON.stringify(step.event, null, 2)),
    ),
  );
}

function renderLog(scenario) {
  byId("log").replaceChildren(
    ...scenario.steps.map((step, index) => {
      const rejected = step.outcome === "rejected";
      const selected = index === view.step;
      const open = rejected || selected;
      const line = html(
        "button",
        {
          type: "button",
          class: "line",
          "data-step": index,
          "data-focus": `step-${index}`,
          "aria-expanded": String(open),
          "aria-controls": open ? `detail-${step.index}` : undefined,
          "aria-current": selected ? "step" : undefined,
        },
        html("span", { class: "number" }, pad(index)),
        html("span", { class: "time" }, elapsed(scenario, step)),
        html("span", { class: "event" }, step.event.type),
        html("span", { class: "node" }, nodeOf(step.event)),
        html("span", { class: "arguments" }, argumentsOf(step.event)),
        html(
          "span",
          { class: "outcome" },
          rejected ? `✗ ${step.rejection?.code ?? "rejected"}` : "applied",
          rejected ? hidden(" (rejected)") : null,
        ),
      );
      const classes = [rejected ? "is-rejected" : "", selected ? "is-selected" : ""].filter(Boolean).join(" ");
      return html("li", { class: classes || undefined }, line, open ? renderDetail(step) : null);
    }),
  );
}

function renderProvenance(scenario) {
  const applied = scenario.steps.filter((step) => step.outcome === "applied").length;
  byId("provenance").replaceChildren(
    html("span", { class: scenario.replayMatches ? "replay ok" : "replay failed" }, scenario.replayMatches ? "✓" : "✗"),
    " ",
    scenario.replayMatches
      ? `Replay check passed: running the ${applied} applied events again from the start gives the same final state (${scenario.finalStatus}).`
      : `Replay check failed: running the ${applied} applied events again from the start gives a different final state.`,
  );
}

function announce(scenario, step) {
  const verdict = step.outcome === "rejected" ? `rejected, ${step.rejection?.code ?? "unknown"}` : "applied";
  byId("announcer").textContent =
    `Event ${view.step + 1} of ${scenario.steps.length}: ${step.event.type} on ${nodeOf(step.event)}, ${verdict}.`;
}

/** Re-rendering replaces the lists, so focus moves back to the rebuilt control with the same key. */
function restoreFocus(key) {
  if (key !== undefined) document.querySelector(`[data-focus="${key}"]`)?.focus({ preventScroll: true });
}

function render({ reveal = false } = {}) {
  const focused = document.activeElement?.dataset?.focus;
  const scenario = view.scenario;
  const step = scenario.steps[view.step];
  renderScenarioList();
  byId("scenario-title").textContent = scenario.title;
  byId("scenario-summary").textContent = scenario.summary;
  renderFacts(scenario);
  renderMatrix(scenario);
  renderLog(scenario);
  renderProvenance(scenario);
  announce(scenario, step);
  restoreFocus(focused);
  if (reveal) {
    // Keep the selected column visible in a scrolled matrix and the selected line in view.
    document.querySelector("#matrix thead .selected")?.scrollIntoView({ block: "nearest", inline: "nearest" });
    document.querySelector(`#log [data-step="${view.step}"]`)?.scrollIntoView({ block: "nearest" });
  }
}

function go(scenarioId, stepIndex, options) {
  const scenario = view.trace.scenarios.find((candidate) => candidate.id === scenarioId) ?? view.trace.scenarios[0];
  if (scenario !== view.scenario) view.labels = attemptLabels(scenario);
  view.scenario = scenario;
  view.step = Math.min(Math.max(stepIndex, 0), scenario.steps.length - 1);
  const hash = `#${scenario.id}/${view.step + 1}`;
  if (location.hash !== hash) history.replaceState(null, "", hash);
  render(options);
}

function fromHash() {
  let hash = location.hash.slice(1);
  try {
    hash = decodeURIComponent(hash);
  } catch {
    // A mangled link (a stray "%") falls back to the raw text, which then matches no scenario.
  }
  const [id, step] = hash.split("/");
  return { id, step: Number.parseInt(step ?? "1", 10) - 1 || 0 };
}

function showLoadError(error) {
  const box = html(
    "div",
    { class: "load-error", role: "alert" },
    html("h2", {}, "The traces did not load"),
    html("p", {}, `trace.json could not be read: ${error.message}.`),
    html(
      "p",
      {},
      "To view them locally, run ",
      html("code", {}, "npm run site"),
      " and serve the ",
      html("code", {}, "site/"),
      " directory over HTTP.",
    ),
  );
  document.body.classList.remove("is-loading");
  byId("main").replaceChildren(box);
}

async function main() {
  try {
    const response = await fetch("trace.json");
    if (!response.ok) throw new Error(`the server answered HTTP ${response.status}`);
    view.trace = await response.json();
    if (!Array.isArray(view.trace.scenarios) || view.trace.scenarios.length === 0) {
      throw new Error("it contains no scenarios");
    }
  } catch (error) {
    showLoadError(error);
    return;
  }

  // Selecting a matrix column or a log line selects that event.
  byId("trace").addEventListener("click", (event) => {
    if (!(event.target instanceof Element) || event.target.closest("pre")) return;
    const target = event.target.closest("[data-step]");
    if (target !== null) go(view.scenario.id, Number(target.dataset.step));
  });
  document.addEventListener("keydown", (event) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    if (event.target instanceof HTMLElement && event.target.closest("input, textarea, select, pre")) return;
    const targets = {
      ArrowRight: view.step + 1,
      j: view.step + 1,
      ArrowLeft: view.step - 1,
      k: view.step - 1,
      Home: 0,
      End: view.scenario.steps.length - 1,
    };
    if (!(event.key in targets)) return;
    event.preventDefault();
    go(view.scenario.id, targets[event.key], { reveal: true });
  });
  // Follow the hash when it changes under an open page: back button, pasted links, scenario links.
  window.addEventListener("hashchange", () => {
    const target = fromHash();
    go(target.id, target.step);
  });

  document.body.classList.remove("is-loading");
  const initial = fromHash();
  go(initial.id, initial.step, { reveal: initial.step > 0 });
}

main();
